insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('nozawa-onsen-japan', '08A', 'Nozawa Onsen', 'Japan', 'A thousand-year onsen village, deep Mt Kenashi powder, and', 'live', 'verified', 'northernLights', 'Japanese Alps/Nagano', '{"ski","adventure","wellness","culture","romance","culinary","family"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["A living 1,300-year Edo-era onsen village + ski resort on Mt Kenashi, ~2 hr from Tokyo via Iiyama Shinkansen + bus","13 free public bathhouses (soto-yu) kept by Yunakama volunteer groups (donation ~JPY 100-300); grand Oyu bathhouse; ~90C Ogama boiling source (Natural Monument, not for bathing)","Terrain: base 565 m to Mt Kenashi summit 1,650 m, vertical 1,085 m, 44.5 km pistes (22.1 easy/13 int/9.4 diff), 16 lifts incl 2 gondolas (skiresort.info; consumer sources higher)","Deep Sea-of-Japan powder ~8-10+ m a season; renowned tree skiing + designated in-bounds powder areas; season late Nov-early May, powder heart Jan-Feb","Resort 2025-26 lift ticket JPY 7,500 adult 1-day / 13,900 2-day / 20,300 3-day / 2,700 night / 3,500 sightseeing gondola","Dosojin Fire Festival every 15 January - one of Japan''s three great fire festivals, Important Intangible Folk Cultural Property (men aged 42 and 25)","Luxury tier is boutique (no international 5-star flag): Kawamotoya ryokan, Residence Yasushi, Kamoshika chalet; deep apartment/chalet rental market","Resort-endorsed backcountry with mandatory Ski-Patrol Backcountry Plan Report; NO dedicated JAN daily bulletin (spine off JAN/JMA + registration + guide)"],"safety":{"emergency":"110 police / 119 fire + ambulance / #7119 medical advice; Nozawa Onsen Ski Patrol +81 269-85-3456; ambulance dispatch free","hospital":"Japanese Red Cross Iiyama Hospital (~20 min ambulance, +81 269-62-4195); Hokushin General (~35 min); Nagano City (~50 min) for major trauma via 119; Abe Clinic +81 269-67-0502 (minor)","malaria":"none","yellow_fever":"not required","activity_note":"SERIOUS AVALANCHE COUNTRY, NO dedicated JAN bulletin: file Backcountry Plan Report with Nozawa Ski Patrol before departing + consult JAN (nadare.jp) + JMA Nagano/Niigata forecasts; backcountry with beacon/probe/shovel + guide only; tree-well/deep-snow immersion suffocation risk (documented fatalities - never ski trees alone); cold/whiteout","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/japan","read":"2026-08-20T14:47:35Z","page_updated":"2026-08-19T15:40:39+01:00","source_country":"japan","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"Deep winter (Christmas/NY + Jan-Feb powder heart + 15 Jan Fire Festival + Lunar New Year + Australian January); limited village beds + multiples/min-stay","shoulder":"Late Nov-mid Dec (early season) + Mar-early May (spring, spring pass from 1 Mar)","green":"May-Nov green season (MTB/gondola summer, hiking, fishing, festivals; lowest rates)","booking_lead":"Christmas/NY + Jan + Fire Festival + best ryokan/chalets 6-12 mo; regular winter 3-6 mo; shoulder 1-3 mo; deposit >90d=20%, <=90d=100%","off_season_specials":"Green-season MTB/hiking/fishing (Jun-Sep); spring-powder value (Mar-Apr); long-stay winter apartments (Nozawa Central from ~JPY 360,000/mo 2-bed)","event_peaks":"Dosojin Fire Festival (15 Jan - sharpest), Christmas/NY, Japanese New Year (Shogatsu), Lunar New Year, Australian school holidays (all January)","fire_date":"Next winter + Fire-Festival weeks + best ryokan/chalets by prior spring/summer (6-12 mo); spring powder from Jan; green-season Nozawa from late winter"},"jewels":[{"name":"Ski Mt Kenashi''s 1,085 m vertical of tree powder","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~JPY 7,500/day; multi-day cheaper/day (approx)","timing":"ski ~late Nov-early May; powder heart Dec-Feb","draw_rank":1,"hook":"from the 1,650 m summit to the village, Nozawa''s tree-lined pistes and designated powder areas